-- 001_init.sql — consolidated initial schema for the Selectel-only OpenVPN-AS bot.
-- Generated by squashing the original 48 incremental migrations into one.
-- run_migrations() applies this with PRAGMA foreign_keys=OFF and swallows
-- duplicate-column errors, so re-running is safe. Add new changes as 002_*.sql;
-- never edit this file.
--
-- Selectel-only schema: the dead pre-fork provider/subscription tables that the
-- squash carried over have been pruned — only the wired-up tables remain.

-- table: bot_settings
CREATE TABLE IF NOT EXISTS bot_settings (
    key   TEXT PRIMARY KEY NOT NULL,
    value TEXT NOT NULL
);

-- table: provider_account_state
CREATE TABLE IF NOT EXISTS provider_account_state (
    provider_type TEXT NOT NULL,
    account_id INTEGER NOT NULL,
    last_error_category TEXT,
    last_error_message TEXT,
    last_error_at TEXT,
    last_success_at TEXT,
    PRIMARY KEY (provider_type, account_id)
);

-- table: selectel_account_regions
CREATE TABLE IF NOT EXISTS selectel_account_regions (
    account_id INTEGER NOT NULL,
    region_id  TEXT    NOT NULL,
    priority   INTEGER NOT NULL,
    PRIMARY KEY (account_id, region_id),
    FOREIGN KEY (account_id) REFERENCES selectel_accounts(id) ON DELETE CASCADE
);

-- table: selectel_accounts
CREATE TABLE IF NOT EXISTS selectel_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    username TEXT NOT NULL,
    password TEXT NOT NULL,
    account_id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    region TEXT NOT NULL DEFAULT 'uz-2',
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- table: server_ip_history
CREATE TABLE IF NOT EXISTS server_ip_history (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    server_id   INTEGER NOT NULL,
    ipv4        TEXT    NOT NULL,
    recorded_at TEXT    NOT NULL DEFAULT (datetime('now'))
);

-- table: servers
CREATE TABLE IF NOT EXISTS servers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    provider_type TEXT NOT NULL DEFAULT 'timeweb',
    provider_account_id INTEGER NOT NULL DEFAULT 0,
    provider_server_id TEXT NOT NULL DEFAULT '',
    ipv4 TEXT,
    root_pass TEXT,
    status TEXT NOT NULL DEFAULT 'creating',
    script_deployed INTEGER NOT NULL DEFAULT 0,
    ip_setup_done INTEGER NOT NULL DEFAULT 0,
    consecutive_curl_fails INTEGER NOT NULL DEFAULT 0,
    consecutive_ssh_fails INTEGER NOT NULL DEFAULT 0,
    ssh_fail_notified_at TEXT,
    front_published INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    deleted_at TEXT
, floating_ip_id TEXT, tx_baseline_bytes INTEGER, tx_baseline_month TEXT, delete_failed_at TEXT, region TEXT, hardened INTEGER NOT NULL DEFAULT 0, park_retry_at TEXT);

-- table: test_urls
CREATE TABLE IF NOT EXISTS test_urls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL UNIQUE,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- index: idx_server_ip_history_ipv4
CREATE INDEX IF NOT EXISTS idx_server_ip_history_ipv4 ON server_ip_history (ipv4);

-- Seed: default TM-blocked test URLs (used by the SSH curl test).
INSERT OR IGNORE INTO test_urls (id, url, is_active) VALUES
    (1, 'https://turkmenistanairlines.tm/', 1),
    (2, 'https://railway.gov.tm/', 1);
